// Walk mode: the textures, all drawn in code (nothing painted or generated by an image tool). Each is a tile that
// repeats across the world at about one texel per screen pixel (TEXEL a world unit), and carries a height in its alpha
// (1 = the surface, lower = sunk into it) for the parallax depth: mortar between bricks, grout between tiles, cracks,
// joints, the aggregate in the road. "Detail" tiles sit around mid-grey and multiply the piece's own colour; "colour"
// tiles (brick, wood, rust, asphalt, paving) carry their own colour and are mixed in.
'use strict';
const TEXEL = 150;
const TEX = (() => {
  let seed = 1;
  const rnd = () => { seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  const rr = (a, b) => a + (b - a)*rnd();
  function noiseGrid(n, cells){ const g = new Float32Array(cells*cells); for (let i = 0; i < g.length; i++) g[i] = rnd();
    const at = (x, y) => g[(((y % cells) + cells) % cells)*cells + (((x % cells) + cells) % cells)];
    return (x, y) => { const fx = x/n*cells, fy = y/n*cells, x0 = Math.floor(fx), y0 = Math.floor(fy), tx = fx - x0, ty = fy - y0, sx = tx*tx*(3 - 2*tx), sy = ty*ty*(3 - 2*ty);
      return (at(x0, y0)*(1 - sx) + at(x0 + 1, y0)*sx)*(1 - sy) + (at(x0, y0 + 1)*(1 - sx) + at(x0 + 1, y0 + 1)*sx)*sy; }; }
  function fbm(n, base, oct){ const L = []; for (let o = 0; o < oct; o++) L.push(noiseGrid(n, base << o)); return (x, y) => { let v = 0, a = .5, s = 0; for (const f of L){ v += f(x, y)*a; s += a; a *= .5; } return v/s; }; }
  const cl = v => Math.max(0, Math.min(255, v | 0));
  function tile(n){ return { n, d: new Uint8Array(n*n*4), h: new Float32Array(n*n).fill(1) }; }
  const I = (T, x, y) => ((((y | 0) % T.n) + T.n) % T.n)*T.n + ((((x | 0) % T.n) + T.n) % T.n);
  const put = (T, x, y, r, g, b) => { const i = I(T, x, y)*4; T.d[i] = cl(r); T.d[i + 1] = cl(g); T.d[i + 2] = cl(b); };
  const get = (T, x, y) => { const i = I(T, x, y)*4; return [T.d[i], T.d[i + 1], T.d[i + 2]]; };
  const mul = (T, x, y, k, kg = k, kb = k) => { const [r, g, b] = get(T, x, y); put(T, x, y, r*k, g*kg, b*kb); };
  const H = (T, x, y, h) => { T.h[I(T, x, y)] = h; };
  const Hmin = (T, x, y, h) => { const i = I(T, x, y); if (h < T.h[i]) T.h[i] = h; };
  const Hadd = (T, x, y, d) => { const i = I(T, x, y); T.h[i] = Math.max(0, Math.min(1, T.h[i] + d)); };
  const Hget = (T, x, y) => T.h[I(T, x, y)];
  function finish(T, soft = true){
    for (let i = 0; i < T.n*T.n; i++) T.d[i*4 + 3] = cl(T.h[i]*255);
    const t = new THREE.DataTexture(T.d, T.n, T.n, THREE.RGBAFormat); t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.magFilter = THREE.LinearFilter; t.minFilter = soft ? THREE.LinearMipmapLinearFilter : THREE.LinearFilter; t.generateMipmaps = !!soft; t.needsUpdate = true; t.userData = { n: T.n }; return t;
  }
  // a crack: a random walk that darkens and sinks
  function crack(T, x, y, len, k = .6, depth = .35){ let a = rr(0, Math.PI*2); for (let s = 0; s < len; s++){ mul(T, x, y, k); Hmin(T, x, y, depth); if (rnd() < .35){ mul(T, x + 1, y, .85); Hmin(T, x + 1, y, depth + .25); } if (rnd() < .04) crack(T, x, y, len*.3, k, depth); a += rr(-.55, .55); x += Math.cos(a); y += Math.sin(a); } }
  function pit(T, x, y, r, dh, k){ for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++){ const q = (dx*dx + dy*dy)/(r*r); if (q < 1){ Hadd(T, x + dx, y + dy, -dh*(1 - q)); if (k) mul(T, x + dx, y + dy, 1 + (k - 1)*(1 - q)); } } }
  function streak(T, x, y0, L, k, w = 1){ for (let s = 0; s < L; s++) for (let q = 0; q < w; q++) mul(T, x + q, y0 + s, 1 - (1 - k)*(1 - s/L)); }
  const T = {};

  // ---- render (walls): mottled, sunk joints, hairline cracks that sink, chips, a few raised patches, rain runs
  seed = 11; { const N = 512, C = tile(N), f = fbm(N, 4, 5), f2 = fbm(N, 24, 3), f3 = fbm(N, 64, 2);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 124 + (f(x, y) - .5)*44 + (f2(x, y) - .5)*20 + rr(-5, 5); put(C, x, y, v + 2, v + 1, v - 2); H(C, x, y, .78 + (f2(x, y) - .5)*.12 + (f3(x, y) - .5)*.14); }
    for (let y = 0; y < N; y += 96) for (let x = 0; x < N; x++){ mul(C, x, y, .78); H(C, x, y, .45); mul(C, x, y + 1, 1.08); }        // render joints
    for (let k = 0; k < 40; k++) crack(C, rr(0, N), rr(0, N), rr(12, 70), .58, .25);
    for (let k = 0; k < 30; k++) pit(C, rr(0, N) | 0, rr(0, N) | 0, rr(2, 6) | 0, .4, .85);                                             // chips knocked out
    for (let k = 0; k < 14; k++){ const x0 = rr(0, N) | 0, y0 = rr(0, N) | 0, w = rr(10, 30) | 0, h = rr(6, 18) | 0;                     // patches skimmed over, a little proud
      for (let y = 0; y < h; y++) for (let x = 0; x < w; x++){ const e = Math.min(x, y, w - x, h - y); if (e < 0) continue; const [r, g, b] = get(C, x0 + x, y0 + y); put(C, x0 + x, y0 + y, r*.94 + 8, g*.94 + 8, b*.94 + 8); Hadd(C, x0 + x, y0 + y, e < 1 ? .05 : .1); } }
    for (let k = 0; k < 36; k++) streak(C, rr(0, N) | 0, rr(0, N) | 0, rr(20, 100) | 0, rr(.74, .86), rnd() < .3 ? 2 : 1);
    T.plaster = finish(C); }
  // ---- concrete: formwork panels and their joints, tie holes, aggregate pits, cracks
  seed = 12; { const N = 512, C = tile(N), f = fbm(N, 8, 4), f2 = fbm(N, 48, 2);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ let v = 122 + (f(x, y) - .5)*34 + rr(-9, 9); let h = .8 + (f2(x, y) - .5)*.12; if (rnd() < .03){ v += rr(12, 26); h += .05; } if (rnd() < .02){ v -= 25; h -= .3; }
      if (y % 128 === 0 || x % 192 === 0){ v -= 26; h = .4; } put(C, x, y, v, v, v + 3); H(C, x, y, h); }
    for (let y = 32; y < N; y += 64) for (let x = 48; x < N; x += 96){ pit(C, x, y, 3, .7, .5); if (rnd() < .6) for (let s = 0; s < rr(10, 40); s++) mul(C, x, y + 3 + s, .82, .76, .7); }
    for (let k = 0; k < 26; k++) crack(C, rr(0, N), rr(0, N), rr(10, 50), .62, .3);
    T.concrete = finish(C); }
  // ---- asphalt (colour): aggregate stones standing proud, tar seams, sunk cracks, a pothole, oil, a patched repair
  seed = 13; { const N = 512, C = tile(N), f = fbm(N, 6, 4);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 50 + (f(x, y) - .5)*16 + rr(-5, 5); put(C, x, y, v, v + 1, v + 5); H(C, x, y, .62 + (f(x, y) - .5)*.1); }
    for (let k = 0; k < 9000; k++){ const x = rr(0, N) | 0, y = rr(0, N) | 0, r = rnd() < .2 ? 2 : 1, l = rr(70, 120); for (let dy = 0; dy < r; dy++) for (let dx = 0; dx < r; dx++){ put(C, x + dx, y + dy, l, l, l + 4); Hadd(C, x + dx, y + dy, .2 + rnd()*.15); } }
    for (let k = 0; k < 3; k++){ const x0 = rr(0, N) | 0, y0 = rr(0, N) | 0, w = rr(50, 120) | 0, h = rr(36, 80) | 0; for (let y = 0; y < h; y++) for (let x = 0; x < w; x++){ const e = Math.min(x, y, w - x, h - y); put(C, x0 + x, y0 + y, e < 2 ? 24 : 38 + rr(-4, 4), e < 2 ? 24 : 39, e < 2 ? 28 : 44); H(C, x0 + x, y0 + y, e < 2 ? .5 : .7 + rr(-.03, .03)); } }
    for (let k = 0; k < 8; k++){ let x = rr(0, N), y = rr(0, N), a = rr(0, 6.3); for (let s = 0; s < 160; s++){ put(C, x, y, 24, 24, 28); put(C, x + 1, y, 30, 30, 34); H(C, x, y, .78); H(C, x + 1, y, .74); a += rr(-.25, .25); x += Math.cos(a); y += Math.sin(a); } }
    for (let k = 0; k < 24; k++) crack(C, rr(0, N), rr(0, N), rr(20, 80), .55, .15);
    for (let k = 0; k < 2; k++){ const x0 = rr(0, N) | 0, y0 = rr(0, N) | 0, r = rr(10, 16); for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++){ const q = Math.hypot(dx, dy*1.3)/r + rr(-.12, .12); if (q < 1){ H(C, x0 + dx, y0 + dy, .12 + rnd()*.15 + q*.2); mul(C, x0 + dx, y0 + dy, .7); } } }   // potholes
    for (let k = 0; k < 10; k++){ const x = rr(0, N) | 0, y = rr(0, N) | 0, r = rr(6, 16) | 0; for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) if (dx*dx + dy*dy < r*r) mul(C, x + dx, y + dy, .78, .78, .86); }
    T.asphalt = finish(C); }
  // ---- pavement tiles (colour): slabs with bevelled edges standing above sunk grout, chipped corners, moss in the joints
  seed = 14; { const N = 512, C = tile(N), s = 32;
    for (let ty = 0; ty < N/s; ty++) for (let tx = 0; tx < N/s; tx++){ const sh = rr(-14, 14), warm = rr(-4, 4), tilt = rr(-.04, .04), tilt2 = rr(-.04, .04);
      for (let y = 0; y < s; y++) for (let x = 0; x < s; x++){ const e = Math.min(x, y, s - 1 - x, s - 1 - y); const grout = e === 0;
        const v = grout ? 70 : 132 + sh + rr(-8, 8) + (e === 1 ? 6 : 0); put(C, tx*s + x, ty*s + y, v + warm, v - 2, v - 7 - warm);
        H(C, tx*s + x, ty*s + y, grout ? .25 : e === 1 ? .82 : .92 + tilt*(x/s - .5) + tilt2*(y/s - .5) + rr(-.015, .015)); }
      if (rnd() < .25){ const cx = tx*s + (rnd() < .5 ? 1 : s - 5), cy = ty*s + (rnd() < .5 ? 1 : s - 5); for (let q = 0; q < 16; q++){ const qx = cx + (q % 4), qy = cy + (q/4 | 0); if (rnd() < .8){ mul(C, qx, qy, .7); H(C, qx, qy, .5); } } }
      if (rnd() < .2) crack(C, tx*s + 16, ty*s + 16, 18, .6, .4);
      for (let x = 0; x < s; x++) if (rnd() < .22){ put(C, tx*s + x, ty*s, 70 + rr(0, 20), 100 + rr(0, 30), 48); H(C, tx*s + x, ty*s, .45); }
      for (let y = 0; y < s; y++) if (rnd() < .22){ put(C, tx*s, ty*s + y, 70 + rr(0, 20), 100 + rr(0, 30), 48); H(C, tx*s, ty*s + y, .45); }
      if (rnd() < .15){ const gx = tx*s + rr(5, 27), gy = ty*s + rr(5, 27); put(C, gx, gy, 60, 58, 62); put(C, gx + 1, gy, 64, 62, 66); Hadd(C, gx, gy, .05); }
    }
    T.paving = finish(C); }
  // ---- brick (colour): running bond, each brick its own red with a rounded face, mortar sunk well back, chipped arrises
  seed = 15; { const N = 512, C = tile(N), bw = 32, bh = 11;
    for (let row = 0; row < Math.ceil(N/bh) + 1; row++){ const off = row % 2 ? bw/2 : 0;
      for (let k = -1; k <= N/bw; k++){ const r0 = rr(112, 165), g0 = r0*rr(.4, .5), b0 = r0*rr(.3, .38), burnt = rnd() < .12, proud = rr(-.04, .04);
        for (let y = 0; y < bh; y++) for (let x = 0; x < bw; x++){ const mort = y >= bh - 2 || x >= bw - 2; const n = rr(-12, 12), e = Math.min(x, y, bw - 3 - x, bh - 3 - y);
          const px = k*bw + off + x, py = row*bh + y;
          if (mort){ put(C, px, py, 146 + n*.3, 140 + n*.3, 128); H(C, px, py, .3 + rnd()*.06); }
          else { const sh = e === 0 ? .85 : 1; put(C, px, py, (burnt ? r0*.6 : r0)*sh + n, (burnt ? g0*.6 : g0)*sh + n, (burnt ? b0*.6 : b0)*sh + n); H(C, px, py, e === 0 ? .78 : .92 + proud + rr(-.02, .02)); } }
        if (rnd() < .3){ const cx = k*bw + off + (rnd() < .5 ? 0 : bw - 5), cy = row*bh + (rnd() < .5 ? 0 : bh - 5); for (let q = 0; q < 9; q++) if (rnd() < .7) H(C, cx + q % 3, cy + (q/3 | 0), .55); } } }
    for (let k = 0; k < 14; k++) pit(C, rr(0, N) | 0, rr(0, N) | 0, rr(5, 14) | 0, 0, 1.12);                                             // efflorescence
    for (let k = 0; k < 16; k++) streak(C, rr(0, N) | 0, rr(0, N) | 0, rr(20, 70) | 0, .78, 2);
    T.brick = finish(C); }
  // ---- painted metal: panel seams sunk, rivet heads raised, scratches, chips to bare steel, rust specks
  seed = 16; { const N = 256, C = tile(N), f = fbm(N, 8, 3);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 124 + (f(x, y) - .5)*22 + rr(-4, 4); put(C, x, y, v, v, v + 3); H(C, x, y, .8 + (f(x, y) - .5)*.04); }
    for (let k = 0; k < 90; k++){ const x = rr(0, N), y = rr(0, N), L = rr(3, 14) | 0, dx = rr(-1, 1), dy = rr(-.3, .3); for (let s = 0; s < L; s++){ put(C, x + dx*s, y + dy*s, 170, 170, 174); Hadd(C, x + dx*s, y + dy*s, -.05); } }
    for (let k = 0; k < 40; k++) pit(C, rr(0, N) | 0, rr(0, N) | 0, rr(1, 3) | 0, .1, 0), mul(C, rr(0, N) | 0, rr(0, N) | 0, 1.1, .78, .55);
    for (let y = 0; y < N; y += 128){ for (let x = 0; x < N; x++){ mul(C, x, y, .6); H(C, x, y, .45); mul(C, x, y + 1, 1.15); }
      for (let x = 6; x < N; x += 16) for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++){ const q = dx*dx + dy*dy; H(C, x + dx, y + 6 + dy, q === 0 ? 1 : q === 1 ? .95 : .88); if (q === 0) put(C, x, y + 6, 175, 175, 180); } }
    T.metal = finish(C); }
  // ---- corrugated sheet: deep ribs, rust runs from the top, dents
  seed = 17; { const N = 256, C = tile(N);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const p = x % 12, ph = p/12*Math.PI*2, v = 128 + Math.sin(ph)*26 + rr(-5, 5); put(C, x, y, v, v, v + 2); H(C, x, y, .5 + .5*Math.cos(ph)); }
    for (let k = 0; k < 26; k++){ const x = rr(0, N) | 0, L = rr(14, 90) | 0, y0 = rr(0, N) | 0; for (let s = 0; s < L; s++){ const a = .55*(1 - s/L); const [r, g, b] = get(C, x, y0 + s); put(C, x, y0 + s, r + (150 - r)*a, g + (84 - g)*a, b + (50 - b)*a); } }
    for (let k = 0; k < 6; k++) pit(C, rr(0, N) | 0, rr(0, N) | 0, rr(4, 9) | 0, .25, .85);
    T.corr = finish(C); }
  // ---- roller shutter: rounded slats with sunk joints
  seed = 18; { const N = 128, C = tile(N);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const p = y % 6, v = [150, 162, 156, 144, 128, 78][p] + rr(-4, 4); put(C, x, y, v, v, v + 4); H(C, x, y, [.8, .95, 1, .95, .82, .35][p]); }
    T.shutter = finish(C); }
  // ---- rust (colour): flaking scale, pitted
  seed = 19; { const N = 256, C = tile(N), f = fbm(N, 8, 4), g2 = fbm(N, 32, 2);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = f(x, y), w = g2(x, y); put(C, x, y, 105 + v*80 + rr(-10, 10), 46 + v*42 + w*16, 24 + v*20); H(C, x, y, .6 + w*.35);
      if (w > .7){ put(C, x, y, 66, 44, 36); H(C, x, y, .35); } if (w < .25 && rnd() < .3){ put(C, x, y, 180, 110, 60); Hadd(C, x, y, .1); } }
    T.rust = finish(C); }
  // ---- wood planks (colour): grain ridges, knots, gaps between boards, nail holes
  seed = 20; { const N = 256, C = tile(N), pw = 21;
    for (let p = 0; p < Math.ceil(N/pw); p++){ const base = rr(92, 134), ph = rr(0, 10), proud = rr(-.05, .05);
      for (let y = 0; y < N; y++) for (let x = 0; x < pw; x++){ const gr = Math.sin((y + ph)*.3 + Math.sin(x*.45 + p)*2.2); let v = base + gr*9 + rr(-5, 5); const gap = x === 0;
        put(C, p*pw + x, y, gap ? 40 : v, gap ? 30 : v*.73, gap ? 22 : v*.5); H(C, p*pw + x, y, gap ? .2 : .85 + proud + gr*.04 - (x === 1 || x === pw - 1 ? .08 : 0)); }
      for (let k = 0; k < 2; k++) pit(C, p*pw + 10, rr(0, N) | 0, 3, .15, .6); for (let y = 8; y < N; y += 64){ put(C, p*pw + 3, y, 40, 30, 22); H(C, p*pw + 3, y, .4); } }
    T.wood = finish(C); }
  // ---- cardboard (colour): flutes
  seed = 22; { const N = 128, C = tile(N);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 160 + (x % 4 === 0 ? -9 : 0) + rr(-7, 7); put(C, x, y, v, v*.78, v*.52); H(C, x, y, x % 4 === 0 ? .8 : .9); }
    T.card = finish(C); }
  // ---- glass: faint grime (flat)
  seed = 23; { const N = 128, C = tile(N), f = fbm(N, 4, 3);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 118 + (f(x, y) - .5)*30 + rr(-3, 3); put(C, x, y, v - 3, v, v + 6); }
    T.glass = finish(C); }
  // ---- canvas cloth: a raised weave, soiling
  seed = 24; { const N = 128, C = tile(N), f = fbm(N, 4, 3);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const w = ((x + y) % 2) ? 7 : -7; const v = 132 + w + (f(x, y) - .5)*34 + rr(-4, 4); put(C, x, y, v, v, v - 3); H(C, x, y, (x + y) % 2 ? .9 : .7); }
    T.canvas = finish(C); }
  // ---- organic (fruit, veg, soil)
  seed = 25; { const N = 128, C = tile(N), f = fbm(N, 8, 3);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 120 + (f(x, y) - .5)*60 + rr(-8, 8); put(C, x, y, v, v, v); H(C, x, y, .6 + f(x, y)*.4); }
    T.organic = finish(C); }
  // ---- worn paint (markings, hazard): the paint stands a hair above the worn spots
  seed = 26; { const N = 256, C = tile(N), f = fbm(N, 8, 4);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = f(x, y), worn = v > .64 || rnd() < .04; const b = 136 + rr(-6, 6); put(C, x, y, worn ? 86 : b, worn ? 86 : b, worn ? 92 : b - 4); H(C, x, y, worn ? .7 : .9); }
    T.paint = finish(C); }
  // ---- neon tube / bulb
  seed = 28; { const N = 32, C = tile(N);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 220 + rr(-10, 10) - (y % 8 === 0 ? 40 : 0); put(C, x, y, v, v, v); }
    T.glow = finish(C, false); T.interior = T.glow; }
  // ---- grime: big soft drips and dirt
  seed = 29; { const N = 256, C = tile(N), f = fbm(N, 4, 3);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = 200 + (f(x, y) - .5)*60; put(C, x, y, v, v, v); }
    for (let k = 0; k < 40; k++) streak(C, rr(0, N) | 0, rr(0, N) | 0, rr(20, 120) | 0, .65, rr(1, 4) | 0);
    T.grime = finish(C); }
  // ---- puddles: where water pools on flat ground
  seed = 30; { const N = 256, C = tile(N), f = fbm(N, 4, 4);
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++){ const v = f(x, y); const p = v > .57 ? 255 : v > .52 ? (v - .52)/.05*255 : 0; put(C, x, y, p, p, p); }
    T.puddle = finish(C); }
  return T;
})();
